const now = new Date().toISOString();
let runtime = global.get("smarthome_runtime");
if (!runtime || typeof runtime !== "object") {
    runtime = {
        schema_version: 1,
        initialized_at: now,
        devices: {},
        master: {},
        diag: {
            booted_at: now,
            last_boot_reason: "startup"
        }
    };
} else {
    runtime.devices = runtime.devices || {};
    runtime.master = runtime.master || {};
    runtime.diag = runtime.diag || {};
    runtime.diag.booted_at = now;
    runtime.diag.last_boot_reason = "restart";
}
global.set("smarthome_runtime", runtime);
msg.payload = {
    status: "bootstrapped",
    initialized_at: runtime.initialized_at,
    device_count: Object.keys(runtime.devices).length,
    master_count: Object.keys(runtime.master).length
};
return msg;
